--liquibase formatted sql

-- Этап 2, существа (contract): таблицы вложенных частей больше не нужны, данные — в jsonb (0009).
-- Rollback восстанавливает таблицы из jsonb (id выдаются заново, в порядке элементов массива).

--changeset pg-migration:0010-drop-creature_saving_throws
DROP TABLE creature_saving_throws;
--rollback CREATE TABLE creature_saving_throws (id integer generated by default as identity PRIMARY KEY, ability varchar(255) COLLATE ci, additional_bonus varchar(255) COLLATE ci, bonus smallint NOT NULL, creature_id integer NOT NULL REFERENCES creatures (id));
--rollback INSERT INTO creature_saving_throws (creature_id, ability, bonus, additional_bonus) SELECT c.id, x.v ->> 'ability', COALESCE((x.v ->> 'bonus')::smallint, 0), x.v ->> 'additionalBonus' FROM creatures c CROSS JOIN LATERAL jsonb_array_elements(c.saving_throws) WITH ORDINALITY AS x(v, n) ORDER BY c.id, x.n;

--changeset pg-migration:0010-drop-creature_skills
DROP TABLE creature_skills;
--rollback CREATE TABLE creature_skills (id integer generated by default as identity PRIMARY KEY, additional_bonus varchar(255) COLLATE ci, bonus smallint NOT NULL, type varchar(255) COLLATE ci, creature_id integer REFERENCES creatures (id));
--rollback INSERT INTO creature_skills (creature_id, type, bonus, additional_bonus) SELECT c.id, x.v ->> 'type', COALESCE((x.v ->> 'bonus')::smallint, 0), x.v ->> 'additionalBonus' FROM creatures c CROSS JOIN LATERAL jsonb_array_elements(c.skills) WITH ORDINALITY AS x(v, n) ORDER BY c.id, x.n;

--changeset pg-migration:0010-drop-creature_feats
DROP TABLE creature_feats;
--rollback CREATE TABLE creature_feats (id integer generated by default as identity PRIMARY KEY, description text COLLATE ci, english_name varchar(255) COLLATE ci, markdown boolean DEFAULT false, name varchar(255) COLLATE ci, creature_id integer REFERENCES creatures (id));
--rollback INSERT INTO creature_feats (creature_id, name, english_name, description, markdown) SELECT c.id, x.v ->> 'name', x.v ->> 'englishName', x.v ->> 'description', COALESCE((x.v ->> 'markdown')::boolean, false) FROM creatures c CROSS JOIN LATERAL jsonb_array_elements(c.feats) WITH ORDINALITY AS x(v, n) ORDER BY c.id, x.n;

--changeset pg-migration:0010-drop-creature_spellcaster
DROP TABLE creature_spellcaster;
--rollback CREATE TABLE creature_spellcaster (id integer generated by default as identity PRIMARY KEY, attack smallint, dc smallint, level smallint, slot1 smallint, slot2 smallint, slot3 smallint, slot4 smallint, slot5 smallint, slot6 smallint, slot7 smallint, slot8 smallint, slot9 smallint, spell_ability varchar(255) COLLATE ci, creature_id integer REFERENCES creatures (id));
--rollback INSERT INTO creature_spellcaster (creature_id, level, dc, attack, spell_ability, slot1, slot2, slot3, slot4, slot5, slot6, slot7, slot8, slot9) SELECT c.id, (x.v ->> 'level')::smallint, (x.v ->> 'dc')::smallint, (x.v ->> 'attack')::smallint, x.v ->> 'spellAbility', (x.v ->> 'slot1')::smallint, (x.v ->> 'slot2')::smallint, (x.v ->> 'slot3')::smallint, (x.v ->> 'slot4')::smallint, (x.v ->> 'slot5')::smallint, (x.v ->> 'slot6')::smallint, (x.v ->> 'slot7')::smallint, (x.v ->> 'slot8')::smallint, (x.v ->> 'slot9')::smallint FROM creatures c CROSS JOIN LATERAL jsonb_array_elements(c.spellcasters) WITH ORDINALITY AS x(v, n) ORDER BY c.id, x.n;
